import {createUnitPreview} from './greek-unit-preview.mjs';
import {thumbnail,TYPES,PALETTE,FACTIONS} from './greek-battle-units.mjs';
const $=s=>document.querySelector(s),terrains=['Olive terraces','River crossing','Coastal ridge','Sunlit ruins','Orchard hollow','Rocky pass'],colors=['#b3bd85','#a9bc9c','#d7c398','#cbb99d','#a1b783','#b7ad92'];let layout='edge',field=0,suit=3,troop=4,filled=[true,true,true],mirror=false,mud=false;
const points=(x,y,r)=>Array.from({length:6},(_,i)=>{const a=(i*60-90)*Math.PI/180;return `${x+Math.cos(a)*r},${y+Math.sin(a)*r}`;}).join(' ');
const poly=(x,y,r,fill,stroke='#8b896d',extra='')=>`<polygon points="${points(x,y,r)}" fill="${fill}" stroke="${stroke}" stroke-width="2" ${extra}/>`;
function terrain(x,y,r,i,id){const cx=x,cy=y;let detail='';if(i===1)detail=`<path d="M ${x-r} ${y-r*.2} Q ${x} ${y+r*.55} ${x+r} ${y-r*.4}" fill="none" stroke="#8fb8ba" stroke-width="${r*.22}"/><path d="M ${x-25} ${y-10} L ${x+20} ${y+24}" stroke="#ba9e76" stroke-width="18"/>`;else if(i===2)detail=`<path d="M ${x} ${y-r} Q ${x+r*.7} ${y} ${x-r*.4} ${y+r}" fill="none" stroke="#a3c1ba" stroke-width="${r*.65}"/>`;else if(i===3)detail=Array.from({length:5},(_,j)=>`<rect x="${x-45+j*22}" y="${y-20+(j%2)*20}" width="14" height="27" rx="3" fill="#e4d7b5" stroke="#a99c80"/>`).join('');else if(i===5)detail=Array.from({length:8},(_,j)=>`<path d="M ${x-70+j*19} ${y+30+(j%2)*10} l 15 -40 l 20 40 z" fill="#a19d83" stroke="#8d8a72"/>`).join('');else detail=Array.from({length:12},(_,j)=>{const a=j*2.4,rr=Math.sqrt(j/12)*r*.72;return `<circle cx="${x+Math.cos(a)*rr}" cy="${y+Math.sin(a)*rr}" r="${r*.065}" fill="${i===4?'#778f58':'#81905b'}"/><circle cx="${x+Math.cos(a)*rr+2}" cy="${y+Math.sin(a)*rr-2}" r="${r*.04}" fill="#a0ae74"/>`;}).join('');return `<defs><clipPath id="${id}"><polygon points="${points(x,y,r-2)}"/></clipPath></defs>${poly(x,y+5,r,'#9c9576','#9c9576')}${poly(x,y,r,colors[i])}<g clip-path="url(#${id})">${[.30,.55,.78].map(f=>`<ellipse cx="${x-r*.25}" cy="${y+r*.2}" rx="${r*f}" ry="${r*f*.65}" fill="none" stroke="#fff5d4" stroke-width="2" opacity=".4"/>`).join('')}${detail}</g>`;}
const positions={edge:[[-138,115],[0,194],[138,115]],fan:[[-115,143],[0,182],[115,143]],step:[[-145,130],[-25,201],[95,150]]};
function socket(x,y,i,enemy=false,empty=false){const c={id:`${suit}-${troop}`,c:suit,v:troop},full=!empty&&filled[i%3],r=64,uid=`socket-${enemy?'e':'p'}-${i}`,img=full?thumbnail(c,enemy?'clay':'olive',enemy?'star':'crown',enemy?'#4e819b':'#bd6489'):'';return `<g class="socket" data-socket="${i}" role="button" tabindex="0" aria-label="${enemy?'Proposed opponent':'Your'} squad socket ${i+1}, ${full?'filled':'empty'}">${poly(x,y+5,r,'#c3ba98','#b0a886')}${poly(x,y,r,full?'#f8f1da':'#eee7ce',full?PALETTE[suit]:'#b4ad92',`class="socket-outline" stroke-dasharray="${empty?'5 5':'none'}"`)}${full?`<image href="${img}" x="${x-57}" y="${y-56}" width="114" height="82"/>`:`<text x="${x}" y="${y-10}" text-anchor="middle" font-size="14">${empty?'Mud +1':'Squad '+(i+1)}</text><text x="${x}" y="${y+9}" text-anchor="middle" font-size="11">${empty?'reserved':'tap to place'}</text>`}${poly(x-24,y+35,23,full?PALETTE[suit]:'#d8d0b1',full?PALETTE[suit]:'#b8ae8b')}${poly(x+24,y+35,23,'#fff9e8','#b8ae8b')}<text x="${x-24}" y="${y+40}" text-anchor="middle" font-size="12" style="fill:${full?'#fff8e4':'#847d64'}">${full?FACTIONS[suit].slice(0,3).toUpperCase():'CLR'}</text><text x="${x+24}" y="${y+42}" text-anchor="middle" font-size="21" font-weight="700">${full?troop:'#'}</text>${full?`<text x="${x}" y="${y+80}" text-anchor="middle" font-size="12">${TYPES[troop]}</text>`:''}</g>`;}
let preview=null,modelMode=false;
function render(){if(modelMode&&preview)preview.show(troop,suit);const overview=$('#overview');overview.innerHTML=terrains.map((name,i)=>`<button data-field="${i}" aria-pressed="${i===field}" aria-label="Battlefield ${i+1}: ${name}"><svg viewBox="0 0 120 90" aria-hidden="true">${terrain(60,43,38,i,'mini'+i)}<text x="60" y="49" text-anchor="middle" font-size="18" font-weight="700">${i+1}</text></svg><span>${name}</span></button>`).join('');overview.querySelectorAll('button').forEach(b=>b.onclick=()=>{field=Number(b.dataset.field);render();});const cx=360,cy=mirror?290:220,r=143;const slots=positions[layout];let scene=terrain(cx,cy,r,field,'large');scene+=`<text x="360" y="${cy-48}" text-anchor="middle" font-family="Fraunces" font-size="24">${terrains[field]}</text><text x="360" y="${cy-20}" text-anchor="middle" font-size="12">Battlefield ${field+1} · terrain schematic</text><path d="M 275 ${cy+22} L 445 ${cy+22}" stroke="#a59c80" stroke-width="7" stroke-dasharray="18 3"/><text x="360" y="${cy+50}" text-anchor="middle" font-size="11">Shared battle space · stone wall</text>`;
if(mirror){scene+=`<text x="360" y="31" text-anchor="middle" font-size="13">Opponent mirror · proposed</text>`;for(let i=0;i<3;i++){const [x,y]=slots[i];scene+=socket(cx+x,cy-y,i,true);}}
for(let i=0;i<3;i++){const[x,y]=slots[i];scene+=socket(cx+x,cy+y,i);}if(mud)scene+=socket(610,cy+34,3,false,true);
const h=mirror?590:530;$('#detail').innerHTML=`<svg viewBox="30 ${mirror?0:10} 660 ${h}" role="img" aria-label="${layout} layout: one parent battlefield hex, three nested squad hexes, each with two sub-facets"><title>Battlefield ${field+1} with three nested squad hexes</title>${scene}<text x="360" y="${h-5}" text-anchor="middle" font-size="13">Your squads · color facet + denomination facet</text></svg>`;$('#detail').querySelectorAll('.socket').forEach(el=>{const toggle=()=>{const i=Number(el.dataset.socket);if(i<3){filled[i]=!filled[i];render();}};el.onclick=toggle;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle();}};});document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layout===layout)));$('#tradeoff').textContent={edge:'A · Clearest hierarchy: each squad meets a lower edge. Broad footprint; keeps the battlefield open.',fan:'B · Compact and symmetrical. Squads gather close; best candidate for a small phone screen.',step:'C · A more playful chain of interlocking hexes. Asymmetric footprint; needs careful reading order.'}[layout];$('#caption').textContent=`Six fields · ${filled.filter(Boolean).length} of three squad sockets filled · ${mirror?'opponent mirror proposed':'opponent mirror hidden'} · no victory-rule choice implied`;}
for(let i=1;i<=10;i++){const o=document.createElement('option');o.value=i;o.textContent=`${i} · ${TYPES[i]}`;$('#troop').append(o);}$('#troop').value=troop;$('#troop').onchange=e=>{troop=Number(e.target.value);render();};$('#suit').onchange=e=>{suit=Number(e.target.value);render();};$('#filled').onchange=e=>{filled=Array.from({length:3},(_,i)=>i<Number(e.target.value));render();};$('#mirror').onchange=e=>{mirror=e.target.checked;render();};$('#mud').onchange=e=>{mud=e.target.checked;render();};document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{layout=b.dataset.layout;render();});$('#compare').onclick=()=>{$('#layout-main').classList.toggle('controls');$('#layout-panel').scrollTop=0;};$('#reset-layout').onclick=()=>{layout='edge';field=0;suit=3;troop=4;filled=[true,true,true];mirror=mud=false;$('#mirror').checked=$('#mud').checked=false;$('#suit').value=3;$('#troop').value=4;$('#filled').value=3;render();};
$('#model-mode').onclick=()=>{modelMode=!modelMode;$('#drawing').classList.toggle('model-mode',modelMode);$('#unit-preview').hidden=!modelMode;$('#detail').hidden=modelMode;$('#fit-unit').hidden=!modelMode;$('#model-help').hidden=!modelMode;$('#model-mode').textContent=modelMode?'Hex layouts':'Unit model';if(modelMode){if(!preview)preview=createUnitPreview($('#unit-preview'));preview.show(troop,suit);$('#caption').textContent=TYPES[troop]+' · actual reusable 3D model and squad · denomination is type/strength, not headcount';}else render();};$('#fit-unit').onclick=()=>preview?.fit();
const move=()=>{const b=$('#app-settings-toggle');if(!b)return false;$('#layout-toolbar').append(b);return true;};if(!move()){const observer=new MutationObserver(()=>{if(move())observer.disconnect();});observer.observe(document.body,{childList:true});}render();if(new URLSearchParams(location.search).get('view')==='unit')$('#model-mode').click();
